// MARK: agent (write)

public enum AgentActionValue: String, Codable, Sendable, Hashable, CaseIterable, AppEnum {
    case status = "status"
    case install = "install"
    case build = "build"
    case grant = "grant"
    public static let typeDisplayRepresentation: TypeDisplayRepresentation = "Action"
    public static let caseDisplayRepresentations: [AgentActionValue: DisplayRepresentation] = [
        .status: "status",
        .install: "install",
        .build: "build",
        .grant: "grant",
    ]
}

public struct AgentInput: Codable, Sendable, Hashable {
    public var action: AgentActionValue?
    public var from: String?
    public var force: Bool?
    public var developerId: Bool?
    public var adHoc: Bool?
    public var notarize: Bool?
    public var personHere: Bool?
    public init(action: AgentActionValue? = nil, from: String? = nil, force: Bool? = nil, developerId: Bool? = nil, adHoc: Bool? = nil, notarize: Bool? = nil, personHere: Bool? = nil) {
        self.action = action
        self.from = from
        self.force = force
        self.developerId = developerId
        self.adHoc = adHoc
        self.notarize = notarize
        self.personHere = personHere
    }
}

public struct AgentOutput: Codable, Sendable, Hashable {
    public var running: Bool
    public init(running: Bool) {
        self.running = running
    }
}

/// Look after the resident agent: Say whether the resident Ouro Reins Agent that holds the Accessibility grant is running; with a word, build it, install it, or raise the grant dialog (only with a person at the Mac).
@MainActor
public enum AgentAction {
    public static let id = "agent"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (AgentInput) async throws -> AgentOutput)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (AgentInput, Result<AgentOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: AgentInput) async throws -> AgentOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct AgentIntent: AppIntent {
    public static let title: LocalizedStringResource = "Look after the resident agent"
    public static let description = IntentDescription("Say whether the resident Ouro Reins Agent that holds the Accessibility grant is running; with a word, build it, install it, or raise the grant dialog (only with a person at the Mac).")

    @Parameter(title: "Action", description: "status, install, build or grant.")
    public var action: AgentActionValue?
    @Parameter(title: "From", description: "With install: the folder to install from.")
    public var from: String?
    @Parameter(title: "Force", description: "With install: replace what is installed.")
    public var force: Bool?
    @Parameter(title: "Developer ID", description: "With build: sign with a Developer ID certificate.")
    public var developerId: Bool?
    @Parameter(title: "Ad hoc", description: "With build: sign ad hoc.")
    public var adHoc: Bool?
    @Parameter(title: "Notarize", description: "With build: notarize the app.")
    public var notarize: Bool?
    @Parameter(title: "Person here", description: "With grant: only with a person at the Mac.")
    public var personHere: Bool?

    public init() {}

    public init(_ input: AgentInput) {
        self.init()
        self.action = input.action
        self.from = input.from
        self.force = input.force
        self.developerId = input.developerId
        self.adHoc = input.adHoc
        self.notarize = input.notarize
        self.personHere = input.personHere
    }

    public var input: AgentInput {
        AgentInput(action: action, from: from, force: force, developerId: developerId, adHoc: adHoc, notarize: notarize, personHere: personHere)
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        let input = self.input
        let result: Result<AgentOutput, any Error>
        do { result = .success(try await AgentAction.run(input)) } catch { result = .failure(error) }
        if let dialog = AgentAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

