/// Serve one request for another Mac: Serve one request: read a JSON line from stdin and print the reply line. This is what --via runs on the other Mac.
@MainActor
public enum WireAction {
    public static let id = "wire"
    /// The app's handler; every door calls it.
    public static var perform: (@MainActor @Sendable (WireInput) async throws -> WireOutput)?
    /// The question the person is asked, the declaration's confirm: the same words as the confirm sheet and the card.
    public static let confirmation: LocalizedStringResource = "Serve one request: read a JSON line from stdin and print the reply line. This is what --via runs on the other Mac."
    /// How the intent asks the person before it acts. Unset, it asks `confirmation`. A test sets it: return to
    /// confirm, or throw to cancel, and the handler never runs. The app can also set it to ask in its own way.
    public static var confirm: (@MainActor @Sendable (WireInput) async throws -> Void)?
    /// What Siri and Shortcuts say when the App Intent finishes or fails: the result in words, or an error turned into
    /// words (rethrow to let the system show it). Unset, the intent says "Done." and a failure throws.
    public static var dialog: (@MainActor @Sendable (WireInput, Result<WireOutput, any Error>) async throws -> IntentDialog)?

    public static func run(_ input: WireInput) async throws -> WireOutput {
        guard let perform else { throw OuroActionNotBound(action: id) }
        return try await perform(input)
    }
}

public struct WireIntent: AppIntent {
    public static let title: LocalizedStringResource = "Serve one request for another Mac"
    public static let description = IntentDescription("Serve one request: read a JSON line from stdin and print the reply line. This is what --via runs on the other Mac.")

    public init() {}

    public init(_ input: WireInput) {
        self.init()
    }

    public var input: WireInput {
        WireInput()
    }

    @MainActor
    public func perform() async throws -> some IntentResult & ProvidesDialog {
        // Consequential: the person says yes before it acts.
        if let confirm = WireAction.confirm { try await confirm(self.input) } else { try await requestConfirmation(result: .result(dialog: IntentDialog(WireAction.confirmation))) }
        let input = self.input
        let result: Result<WireOutput, any Error>
        do { result = .success(try await WireAction.run(input)) } catch { result = .failure(error) }
        if let dialog = WireAction.dialog { return .result(dialog: try await dialog(input, result)) }
        _ = try result.get()
        return .result(dialog: "Done.")
    }
}

